          ? { ...post, social_reactions: [...(post.social_reactions ?? []).filter((reaction) => reaction.user_id !== incoming.user_id), { user_id: incoming.user_id, reaction: incoming.reaction }] }
          : post));
      })
      .on("postgres_changes", { event: "DELETE", schema: "public", table: "social_reactions" }, (payload) => {
