{posts.map((post) => { const author = authorMap.get(post.author_id); const liked = (post.social_reactions ?? []).some((reaction) => reaction.user_id === userId); return <article key={post.id} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="font-black">{author?.display_name || author?.username || (post.author_id === userId ? profile.display_name || profile.username || "Εσύ" : "Pantavion member")}</div><div className="mt-1 text-xs text-slate-500">{new Date(post.created_at).toLocaleString()}</div>{post.body ? <p className="mt-3 whitespace-pre-wrap text-[15px] leading-6">{post.body}</p> : null}{capabilities.media && post.social_post_media?.length ? <div className="mt-3 grid gap-2 sm:grid-cols-2">{post.social_post_media.map((attachment) => <PostMedia key={attachment.id} attachment={attachment} />)}</div> : null}<div className="mt-4 flex gap-3 border-t border-slate-100 pt-3">{capabilities.reactions ? <button onClick={() => toggleLike(post)} className={`text-sm font-black ${liked ? "text-[#2467aa]" : "text-slate-600"}`}>Μου αρέσει · {post.social_reactions?.length ?? 0}</button> : null}{capabilities.comments ? <span className="text-sm text-slate-500">Σχόλια · {post.social_comments?.length ?? 0}</span> : null}</div>{capabilities.comments ? (post.social_comments ?? []).map((comment) => <div key={comment.id} className="mt-2 rounded-xl bg-slate-50 px-3 py-2 text-sm">{comment.body}</div>) : null}{capabilities.comments ? <CommentBox onSend={(text) => addComment(post.id, text)} /> : null}</article>; })}
